// Package noderoots holds the root certificates for cloud broker TLS
// verification: exactly the roots bundled with the Node version Node-RED runs
// on the gateway (tls.rootCertificates), generated by
// edge/vectors/generate-node-roots.js. No system store is added.
package noderoots

import (
	"crypto/sha256"
	"crypto/x509"
	_ "embed"
	"encoding/hex"
	"encoding/pem"
	"sync"
)

// NodeVersion is the Node release the roots come from.
const NodeVersion = "20.18.3"

//go:embed node-v20.18.3-roots.pem
var rootsPEM []byte

var certificates = sync.OnceValue(func() []*x509.Certificate {
	var certs []*x509.Certificate
	rest := rootsPEM
	for {
		var block *pem.Block
		block, rest = pem.Decode(rest)
		if block == nil {
			break
		}
		cert, err := x509.ParseCertificate(block.Bytes)
		if err != nil {
			panic("noderoots: " + err.Error())
		}
		certs = append(certs, cert)
	}
	return certs
})

// Pool returns a new pool with every root.
func Pool() *x509.CertPool {
	pool := x509.NewCertPool()
	for _, cert := range certificates() {
		pool.AddCert(cert)
	}
	return pool
}

// Fingerprints lists the SHA-256 of each root's DER, in file order.
func Fingerprints() []string {
	var out []string
	for _, cert := range certificates() {
		sum := sha256.Sum256(cert.Raw)
		out = append(out, hex.EncodeToString(sum[:]))
	}
	return out
}
